"""Money value object."""
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP


def _to_cents(amount: "int | float | str | Decimal") -> int:
    """Convert a currency amount to a whole number of cents."""
    if isinstance(amount, float):
        # str() first: Decimal(0.1) would carry the binary noise into the cents.
        decimal_amount = Decimal(str(amount))
    elif isinstance(amount, (int, str, Decimal)):
        decimal_amount = Decimal(amount)
    else:
        raise TypeError(f"cannot make Money from {type(amount).__name__}")
    return int((decimal_amount * 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))


@dataclass(frozen=True, init=False)
class Money:
    """A currency amount held as an exact number of cents.

    The constructor takes an amount in currency units, so ``Money(0.10)`` is
    ten cents; ``Money.from_cents(10)`` is the same value without the
    conversion.
    """

    cents: int

    def __init__(self, amount: "int | float | str | Decimal") -> None:
        object.__setattr__(self, "cents", _to_cents(amount))

    @classmethod
    def from_cents(cls, cents: int) -> "Money":
        money = cls.__new__(cls)
        object.__setattr__(money, "cents", int(cents))
        return money

    @property
    def amount(self) -> float:
        """The value in currency units, for arithmetic that is not exact anyway."""
        return self.cents / 100

    def as_decimal(self) -> Decimal:
        """The value in currency units, exactly, with two decimal places."""
        return Decimal(self.cents).scaleb(-2)

    def __add__(self, other: "Money") -> "Money":
        return Money.from_cents(self.cents + other.cents)

    def __mul__(self, qty: int) -> "Money":
        return Money.from_cents(self.cents * qty)

    def __neg__(self) -> "Money":
        return Money.from_cents(-self.cents)


ZERO = Money.from_cents(0)

